def b91decode(strng):
    b = 0
    n = 0
    out = []
    for c in strng:
        if c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"':
            continue
        v = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'.index(c)
        b |= v << n
        n += 13 if (n + 13) < 32 else 0
        if n > 7:
            out.append(b & 255)
            b >>= 8
            n -= 8
    if n > 0:
        out.append(b & 255)
    return ''.join(map(chr, out))

class Solution:
    def maxSizeSlices(self, slices: List[int]) -> int:
        def dp(arr):
            n = len(arr)
            k = n // 3
            dp = [[0] * (k + 1) for _ in range(n + 1)]
            for i in range(1, n + 1):
                for j in range(1, k + 1):
                    dp[i][j] = max(dp[i - 1][j], (dp[i - 2][j - 1] if i >= 2 else 0) + arr[i - 1])
            return dp[n][k]
        return max(dp(slices[:-1]), dp(slices[1:]))

class Solution:
    def numTimesAllBlue(self, light: List[int]) -> int:
        max_bulb = 0
        count = 0
        for i, bulb in enumerate(light, 1):
            max_bulb = max(max_bulb, bulb)
            if max_bulb == i:
                count += 1
        return count

class Solution:
    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
        partner = {}
        for x, y in pairs:
            partner[x] = y
            partner[y] = x

        unhappy = 0
        for x in range(n):
            y = partner[x]
            for u in preferences[x]:
                if u == y:
                    break
                v = partner[u]
                if preferences[u].index(x) < preferences[u].index(v):
                    unhappy += 1
                    break
        return unhappy

class Solution:
    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        trailing_zeros = [0] * n
        for i in range(n):
            count = 0
            for j in range(n - 1, -1, -1):
                if grid[i][j] == 0:
                    count += 1
                else:
                    break
            trailing_zeros[i] = count
        swaps = 0
        for i in range(n):
            required = n - i - 1
            if trailing_zeros[i] >= required:
                continue
            found = False
            for j in range(i + 1, n):
                if trailing_zeros[j] >= required:
                    found = True
                    while j > i:
                        trailing_zeros[j], trailing_zeros[j - 1] = trailing_zeros[j - 1], trailing_zeros[j]
                        swaps += 1
                        j -= 1
                    break
            if not found:
                return -1
        return swaps
